const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return {}; }
};
const response = items[0]?.json ?? {};
const body = parseBody(response.body ?? response);
const evaluations = Array.isArray(body.evals) ? body.evals : [];
const latest = evaluations[0];
const revision = String(latest?.flake ?? '').match(/[0-9a-f]{40}/)?.[0] ?? '';
return [{ json: {
  available: Boolean(latest?.id),
  evaluationId: latest?.id ?? null,
  revision: revision ? revision.slice(0, 8) : '',
  buildsUrl: latest?.id ? `https://forge.guildedthorn.arpa/eval/${latest.id}/builds` : 'https://forge.guildedthorn.arpa/eval/0/builds',
  evaluationUrl: latest?.id ? `https://forge.guildedthorn.arpa/eval/${latest.id}` : 'https://forge.guildedthorn.arpa/jobset/thornixos/main',
} }];

const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};
const fit = (value, limit = 1024) => {
  const safe = String(value ?? '').replaceAll('@', '@\u200b').trim();
  if (!safe) return 'None.';
  return safe.length <= limit ? safe : safe.slice(0, limit - 2).trimEnd() + '…';
};
const host = (value) => String(value ?? 'unknown').replace('.guildedthorn.arpa', '').split(':')[0];
const socResponse = $('Read SOC operator snapshot').first().json;
const soc = parseBody(socResponse.body ?? socResponse) ?? {};
const metadata = $('Select newest Hydra evaluation').first().json;
const buildResponse = items[0]?.json ?? {};
const buildBody = parseBody(buildResponse.body ?? buildResponse);
const builds = Array.isArray(buildBody) ? buildBody : [];
const expected = [
  'anvil', 'atlas', 'casebook', 'courier', 'forge', 'herald', 'hound',
  'identity', 'loom', 'lure', 'mac', 'mitm', 'nixos', 'oracle', 'pixie',
  'scout', 'sieve', 'soc', 'websites',
].map((name) => `production.${name}`);
const byJob = new Map(builds.map((build) => [build.job, build]));
const states = expected.map((job) => {
  const build = byJob.get(job);
  if (!build || Number(build.finished) !== 1) return { job, state: 'pending' };
  if (Number(build.buildstatus) !== 0 || !Object.values(build.buildoutputs ?? {}).some((output) => output?.path)) return { job, state: 'failed' };
  return { job, state: 'succeeded' };
});
const hydra = {
  available: Boolean(metadata.available) && builds.length > 0,
  revision: metadata.revision || 'unknown',
  evaluationUrl: metadata.evaluationUrl,
  succeeded: states.filter((item) => item.state === 'succeeded').length,
  failed: states.filter((item) => item.state === 'failed'),
  pending: states.filter((item) => item.state === 'pending'),
  total: expected.length,
};
const actions = Array.isArray(soc.actions) ? [...soc.actions] : [];
if (!hydra.available) actions.unshift({ severity: 'warning', message: 'Hydra production evaluation is unavailable' });
else if (hydra.failed.length) actions.unshift({ severity: 'critical', message: `Repair failed Hydra jobs: ${hydra.failed.map((item) => item.job.replace('production.', '')).join(', ')}` });
else if (hydra.pending.length) actions.push({ severity: 'warning', message: `Hydra still has ${hydra.pending.length} production job(s) pending` });
const hasCritical = actions.some((item) => item.severity === 'critical');
const hasWarning = actions.some((item) => item.severity === 'warning');
const status = hasCritical ? 'critical' : hasWarning ? 'warning' : 'healthy';
const colors = { healthy: 0xa6e3a1, warning: 0xf9e2af, critical: 0xf38ba8 };
const fleet = soc.fleet ?? {};
const services = soc.services ?? {};
const deployment = soc.deployment ?? {};
const maintenance = soc.maintenance ?? {};
const security = soc.security ?? {};
const priorities = actions.length
  ? actions.slice(0, 8).map((item) => `${item.severity === 'critical' ? '⛔' : item.severity === 'warning' ? '⚠️' : '🔧'} ${item.message}`).join('\n')
  : '✅ No operator action is currently required.';
const disks = (fleet.top_root_disks ?? []).slice(0, 5).map((item) => `${item.used_percent >= 85 ? '⚠️' : '•'} ${item.host}: **${Number(item.used_percent).toFixed(1)}%**`).join('\n');
const failedUnits = (fleet.failed_units ?? []).length;
const fleetText = [
  `Node exporters: **${Number(fleet.node_targets ?? 0) - (fleet.down_hosts ?? []).length}/${Number(fleet.node_targets ?? 0)} up**`,
  `Failed units: **${failedUnits}** · Service probes down: **${(services.unavailable ?? []).length}**`,
  '', 'Highest root-disk use:', disks || 'No disk telemetry.',
].join('\n');
const hydraIcon = !hydra.available || hydra.failed.length ? '⛔' : hydra.pending.length ? '⏳' : '✅';
const deploymentText = [
  `${hydraIcon} Hydra ${hydra.succeeded}/${hydra.total} built · ${hydra.failed.length} failed · ${hydra.pending.length} pending`,
  `Evaluation revision: **${hydra.revision}**`,
  `Live comin revision: **${String(deployment.majority_commit ?? 'unknown').slice(0, 8)}** across ${Number(deployment.targets ?? 0)} host(s)`,
  `Drifted: **${(deployment.drifted_hosts ?? []).length}** · Reboot pending: **${(deployment.reboot_pending ?? []).length}**`,
  `[Open Hydra evaluation](${hydra.evaluationUrl})`,
].join('\n');
const maintenanceText = [
  `Backups: **${(maintenance.backups ?? []).length - (maintenance.stale_backups ?? []).length}/${(maintenance.backups ?? []).length} fresh**`,
  `Slow endpoints: **${(services.slow ?? []).length}**`,
  `Certificate actions: **${(services.internal_acme_attention ?? []).length + (services.external_tls_attention ?? []).length}**`,
].join('\n');
const securityText = [
  `Suricata alerts: **${Number(security.suricata_alerts ?? 0)}** · pfSense high: **${Number(security.pfsense_high_alerts ?? 0)}**`,
  `SSH failures: **${Number(security.ssh_failures ?? 0)}** · OpenCanary: **${Number(security.opencanary_interactions ?? 0)}**`,
  `CrowdSec scenarios: **${Number(security.crowdsec_scenarios ?? 0)}** · Zeek notices: **${Number(security.zeek_notices ?? 0)}**`,
  '[Open SOC dashboards](https://soc.guildedthorn.arpa:3000/)',
].join('\n');
const chicagoDate = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', weekday: 'long', month: 'short', day: 'numeric' }).format(new Date());
const discordEmbed = {
  author: { name: 'GUILDEDTHORN // MORNING OPS' },
  title: fit(`${status === 'healthy' ? 'All clear' : status === 'warning' ? 'Maintenance needed' : 'Action required'} · ${chicagoDate}`, 256),
  description: 'Your one-card operator view of the fleet, deployment pipeline, maintenance state, and last 24 hours of security telemetry.',
  color: colors[status],
  fields: [
    { name: '🧭 Today’s priorities', value: fit(priorities), inline: false },
    { name: '🖥️ Fleet + storage', value: fit(fleetText), inline: false },
    { name: '🚀 Deployment', value: fit(deploymentText), inline: false },
    { name: '🧰 Maintenance', value: fit(maintenanceText), inline: true },
    { name: '🛡️ Security · 24h', value: fit(securityText), inline: false },
  ],
  footer: { text: 'Loom · fixed read-only SOC queries · no raw logs' },
  timestamp: new Date().toISOString(),
};
return [{ json: { discordEmbed, status, actionCount: actions.length } }];
